PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "questions" (
	id INTEGER PRIMARY KEY AUTOINCREMENT,
	question TEXT
);
CREATE TABLE IF NOT EXISTS endocrinologist (
	name TEXT,
	"day" INTEGER,
	"month" TEXT,
	time INTEGER
);
CREATE TABLE IF NOT EXISTS sugar_log_archive (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    date ANY,
    time ANY,
    sugar INTEGER,
    insulin INTEGER,
    XEBE INTEGER,
    food ANY,
    notes INTEGER,
    protein INTEGER,
    fat INTEGER,
    carb INTEGER,
    ccal INTEGER
);
CREATE TABLE IF NOT EXISTS "sugar_log" (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    date ANY,
    time ANY,
    sugar INTEGER,
    insulin INTEGER,
    XEBE INTEGER,
    food ANY,
    notes INTEGER,
    protein INTEGER,
    fat INTEGER,
    carb INTEGER,
    ccal INTEGER
, auto_food ANY, activity ANY, `food_text` text, `manual_carb` text, `manual_fat` text, `manual_protein` text);
CREATE TABLE IF NOT EXISTS "products" (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    "Продукт" TEXT,
    "Белки" REAL,
    "Жиры" REAL,
    "Углеводы" REAL,
    "Вес продукта" REAL,
    "ккал" TEXT,
    "БЖЕ" TEXT,
    "ХЕ" TEXT,
    "ХЕ + БЖЕ" TEXT,
    "Всего инсулина" TEXT,
    "Порционный" NUMERIC
);
CREATE TABLE IF NOT EXISTS `user_info` (
	`name` text PRIMARY KEY NOT NULL,
	`height` integer,
	`weight` integer,
	`short_insulin` integer,
	`long_insulin` integer,
	`sugar_decline` integer
);
DELETE FROM sqlite_sequence;
CREATE TRIGGER trg_products_insert_insulin
AFTER INSERT ON products
FOR EACH ROW
BEGIN
UPDATE products
SET "Всего инсулина" = NEW."ХЕ + БЖЕ" * (SELECT short_insulin FROM user_info LIMIT 1)
WHERE id = NEW.id;
END;
CREATE TRIGGER trg_products_update_insulin
AFTER UPDATE OF "ХЕ + БЖЕ" ON products
FOR EACH ROW
WHEN NEW."ХЕ + БЖЕ" IS NOT OLD."ХЕ + БЖЕ"
BEGIN
UPDATE products
SET "Всего инсулина" = NEW."ХЕ + БЖЕ" * (SELECT short_insulin FROM user_info LIMIT 1)
WHERE id = NEW.id;
END;
CREATE TRIGGER trg_user_info_update_short_insulin
AFTER UPDATE OF short_insulin ON user_info
FOR EACH ROW
WHEN NEW.short_insulin IS NOT OLD.short_insulin
BEGIN
    UPDATE products
    SET "Всего инсулина" =
        CAST("ХЕ + БЖЕ" AS REAL) * NEW.short_insulin;
END;
COMMIT;
